def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write_complete(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def protected_sources() -> dict[Path, str]:
    result = {}
    prefixes = (
        ROOT / "qseries_v2" / "oracle_intelligence" / "live_acquisition",
        ROOT / "qseries_v2" / "oracle_intelligence" / "analytics",
        ROOT / "qseries_v2" / "oracle_intelligence_integration",
        ROOT / "qseries_v2" / "oracle_research_runtime",
        ROOT / "qseries_v2" / "oracle_operator_runtime",
        ROOT / "qseries_v2" / "qseries",
    )
    for base in prefixes:
        if not base.exists():
            continue
        for path in base.rglob("*.py"):
            if path.is_file():
                result[path] = sha256(path)
    for path in (OIT_005, OIT_006):
        if path.is_file():
            result[path] = sha256(path)
    return result


def main() -> int:
    print("=" * 40)
    print(" OIT-007 INSTALLER")
    print(" QUERYABLE INTELLIGENCE READ MODEL")
    print("=" * 40)
    try:
        if not OIT_005.is_file():
            raise RuntimeError(f"Actual OIT-005 module missing: {OIT_005}")
        if not OIT_006.is_file():
            raise RuntimeError(f"Actual OIT-006 module missing: {OIT_006}")

        oit_006_text = OIT_006.read_text(encoding="utf-8")
        required = (
            'SCHEMA_VERSION = "OIT-006"',
            "consume_admitted_intelligence",
            "select_intelligence_artifact",
            "verify_intelligence_consumption",
            "read_only",
        )
        missing = [item for item in required if item not in oit_006_text]
        if missing:
            raise RuntimeError(
                f"OIT-006 contract incomplete: {missing}"
            )

        protected = protected_sources()
        print("[OK] Actual OIT-005 immutable admission contract verified")
        print("[OK] Actual OIT-006 read-only consumption contract verified")
        print(f"[OK] Protected production source files captured: {len(protected)}")

        write_complete(PRODUCTION, PRODUCTION_SOURCE)
        write_complete(RUNNER, RUNNER_SOURCE)
        write_complete(TEST, TEST_SOURCE)

        export = "from .oracle_queryable_intelligence_read_model import *"
        current = INIT.read_text(encoding="utf-8") if INIT.exists() else ""
        if export not in current.splitlines():
            if current and not current.endswith("\n"):
                current += "\n"
            INIT.write_text(
                current + export + "\n",
                encoding="utf-8",
                newline="\n",
            )
            print(f"[OK] PACKAGE UPDATED: {INIT.resolve()}")
        else:
            print(f"[OK] PACKAGE EXPORT PRESENT: {INIT.resolve()}")
        ast.parse(INIT.read_text(encoding="utf-8"), filename=str(INIT))

        completed = subprocess.run(
            [sys.executable, str(TEST)],
            cwd=ROOT,
            check=False,
        )
        if completed.returncode:
            raise RuntimeError(
                f"OIT-007 test failed with exit code {completed.returncode}"
            )

        for path, expected in protected.items():
            if not path.is_file() or sha256(path) != expected:
                raise RuntimeError(
                    f"Protected production source changed: {path}"
                )

        print("[PASS] OIT-005 and OIT-006 production modules unchanged")
        print("[PASS] OLA, OIA, INT-OII, ORR, OOR, and Q Series unchanged")
        print("[PASS] Queryable intelligence read model installed")
        print("[PASS] Deterministic record normalization installed")
        print("[PASS] Schema, record, and search terminal commands installed")
        print("[PASS] Complete production test passed")
        print(f"[PASS] Repository located: {ROOT}")
        print("[DONE] OIT-007 QUERYABLE INTELLIGENCE READ MODEL INSTALLED")
        return 0
    except (RuntimeError, SyntaxError) as exc:
        print(f"[ERROR] {exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
